        description: {
          es: 'Calle estrecha del centro con una hornacina peculiar: la "cabeza del rey don Pedro" sigue empotrada en su fachada.',
          en: 'Narrow central street with a peculiar niche: the "head of King Pedro" is still embedded in its façade.',
          fr: 'Ruelle du centre avec une niche particulière : la "tête du roi Pierre" est toujours encastrée dans sa façade.',
          de: 'Enge Gasse im Zentrum mit einer besonderen Nische: der "Kopf von König Pedro" steckt noch in der Fassade.',
          it: 'Stretta via del centro con una nicchia particolare: la "testa di re Pedro" è ancora incastonata nella facciata.',
          pt: 'Rua estreita do centro com um nicho peculiar: a "cabeça do rei Pedro" ainda está embutida na fachada.',
        },
        tip: {
          es: 'La leyenda más famosa del rey don Pedro: mató en duelo nocturno al caballero Guzmán que difamaba su honra, y una vecina lo espió desde su ventano con un candil. Para no delatarla, el rey mandó emparedar la cabeza del caballero en la calle (el pueblo creyó durante siglos que era la del propio rey) y puso guardia ante ella. La calle se llama Candilejo por aquel candil.',
          en: 'King Pedro\'s most famous legend: he killed in a night duel the Guzmán knight who defamed his honour, while a neighbour spied from her window with an oil lamp. To protect her, the king had the knight\'s head walled into the street (for centuries people believed it was the king\'s own) and set a guard before it. The street takes its name from that little lamp (candil).',
          fr: 'La légende : le roi Pierre tua en duel nocturne le chevalier Guzmán qui diffamait son honneur, tandis qu\'une voisine l\'espionnait avec une lampe. Pour la protéger, le roi fit murer la tête du chevalier dans la rue (le peuple crut que c\'était celle du roi) et y plaça une garde. La rue doit son nom à cette lampe.',
          de: 'Die Legende: König Pedro tötete im nächtlichen Duell den Ritter Guzmán, der seine Ehre verleumdete, während eine Nachbarin mit einer Öllampe zusah. Um sie zu schützen, ließ der König den Kopf des Ritters in die Straße einmauern (das Volk glaubte, es sei der des Königs) und stellte eine Wache davor. Die Gasse ist nach jener Lampe benannt.',
          it: 'La leggenda: re Pedro uccise in duello notturno il cavaliere Guzmán che diffamava il suo onore, mentre una vicina lo spiava con un lume. Per proteggerla, il re fece murare la testa del cavaliere nella via (il popolo credette fosse quella del re) e vi pose una guardia. La via prende il nome da quel lume.',
          pt: 'A lenda: o rei Pedro matou em duelo noturno o cavaleiro Guzmán que difamava a sua honra, enquanto uma vizinha o espiava com um candeeiro. Para a proteger, o rei mandou emparedar a cabeça do cavaleiro na rua (o povo acreditou que era a do rei) e pôs guarda diante dela. A rua deve o nome a esse candeeiro.',
        },
