          en: 'The tower that survived kings, earthquakes and centuries: Almohad minaret, Renaissance belfry and bronze weathervane.',
          fr: 'La tour qui survécut aux rois, aux tremblements de terre et aux siècles : minaret almohade, clocher Renaissance et girouette de bronze.',
          de: 'Der Turm, der Könige, Erdbeben und Jahrhunderte überlebte: Almohaden-Minarett, Renaissance-Glockenturm und Bronze-Wetterfahne.',
          it: 'La torre che sopravvisse a re, terremoti e secoli: minareto almohade, campanile rinascimentale e banderuola di bronzo.',
          pt: 'A torre que sobreviveu a reis, terramotos e séculos: minarete almóada, campanário renascentista e cata-vento de bronze.',
