        tip: {
          es: 'En 1248 el almirante Ramón de Bonifaz rompió esa cadena lanzando naves cargadas de piedras contra el puente de barcas. La gesta abrió el río a la flota de Fernando III y decidió la conquista de Sevilla. La estatua de Bonifaz sigue al pie de la torre.',
          en: 'In 1248 Admiral Ramón de Bonifaz broke that chain by launching stone-laden ships against the boat bridge. The feat opened the river to Ferdinand III\'s fleet and decided the conquest of Seville. Bonifaz\'s statue still stands at the tower\'s foot.',
          fr: 'En 1248, l\'amiral Ramón de Bonifaz brisa cette chaîne en lançant des navires chargés de pierres contre le pont de barques. L\'exploit ouvrit le fleuve à la flotte de Ferdinand III et décida de la conquête de Séville.',
          de: '1248 durchbrach Admiral Ramón de Bonifaz die Kette, indem er steinbeladene Schiffe gegen die Bootsbrücke schleuderte. Der Coup öffnete den Fluss für Ferdinands III. Flotte und entschied die Eroberung Sevillas.',
          it: 'Nel 1248 l\'ammiraglio Ramón de Bonifaz spezzò quella catena lanciando navi cariche di pietre contro il ponte di barche. L\'impresa aprì il fiume alla flotta di Ferdinando III e decise la conquista di Siviglia.',
          pt: 'Em 1248 o almirante Ramón de Bonifaz rompeu essa corrente lançando naus carregadas de pedras contra a ponte de barcas. A façanha abriu o rio à frota de Fernando III e decidiu a conquista de Sevilha.',
        },
