          en: 'The arcade row beside the Giralda, stage of the city\'s partition after the 1248 conquest.',
          fr: 'La rangée d\'arcades près de la Giralda, théâtre du partage de la ville après la conquête de 1248.',
          de: 'Die Arkadenreihe neben der Giralda, Schauplatz der Stadtaufteilung nach der Eroberung 1248.',
          it: 'La fila di portici accanto alla Giralda, scena della spartizione della città dopo la conquista del 1248.',
          pt: 'A fila de arcadas junto à Giralda, palco da partilha da cidade após a conquista de 1248.',
