          pt: 'Diz-se que em 1625, após um incêndio que destruiu a antiga imagem, o capitão Cepeda prometeu um Cristo nunca visto e modelou-o "em pasta" em vez de madeira. Os trianeiros chamam-lhe El Cachorro e a sua saída na Quarta-feira Santa reúne milhares.',
