          it: 'Cortés, studente fuggito da Medellín dopo un omicidio, cambiò qui i panni da studente con quelli da soldato e si lasciò crescere la barba. A due passi c\'è l\'ospedale Amor de Dios, il cui nome piccante già ironizzava Cervantes.',
