          fr: 'Le port d\'où partaient les navires vers les Indes, et où une gitane arrêta un fugitif avec une prophétie.',
          de: 'Der Hafen, von dem Schiffe nach Indien fuhren, und wo eine Gitana einen Flüchtigen mit einer Prophezeiung aufhielt.',
          it: 'Il porto da cui partivano le navi per le Indie, e dove una gitana fermò un fuggitivo con una profezia.',
          pt: 'O porto de onde partiam as naus para as Índias, e onde uma cigana parou um fugitivo com uma profecia.',
