          it: 'La parrocchia più antica di Triana, eretta su una moschea dopo la conquista. Le patrone dei ceramisti.',
          pt: 'A paróquia mais antiga de Triana, erguida sobre uma mesquita após a conquista. As padroeiras dos oleiros.',
