          en: 'The three Almohad towers were built to the same pattern. The Giralda was meant to be the tallest; its bricks tell the story: look at the sebka panel above the twin arches.',
          fr: 'Les trois tours almohades suivirent le même modèle. La Giralda devait être la plus haute ; ses briques racontent l\'histoire : voyez le panneau de sebka au-dessus des arcs jumeaux.',
