          en: 'The faithful washed here five times a day. The orange trees came later; the central fountain still has the shape of an Almohad basin.',
          fr: 'Les fidèles s\'y lavaient cinq fois par jour. Les orangers vinrent plus tard ; la fontaine centrale garde sa forme de bassin almohade.',
